0 & 2 & 0 \\ 
0 & 0 & 1 \\ 
\end{pmatrix}*
\begin{pmatrix} 
cos(\pi /4) & sin(\pi /4) & 0 \\ 
-sin(\pi /4) & cos(\pi /4) & 0 \\ 
0 & 0 & 1 \\ 
